 *
 *  usage: `testH3Api`
 */

#include <math.h>

#include "h3Index.h"
#include "h3api.h"
#include "latLng.h"
#include "test.h"
#include "utility.h"

SUITE(h3Api) {
    TEST(latLngToCell_res) {
        H3Index h;
        LatLng anywhere = {0, 0};

        t_assert(H3_EXPORT(latLngToCell)(&anywhere, -1, &h) == E_RES_DOMAIN,
                 "resolution below 0 is invalid");
        t_assert(H3_EXPORT(latLngToCell)(&anywhere, 16, &h) == E_RES_DOMAIN,
                 "resolution above 15 is invalid");
    }

